async function rebuildPublicFeed() {
  const [radar, community, control] = await Promise.all([
    db.list<ListingRecord>('radar_jobs', { limit:200 }),
    db.list<ListingRecord>('community_posts', { limit:200 }),
    db.list<PublicFeedControl>('public_feed_control', { limit:1 }),
  ]);
  const updatedAt = new Date().toISOString();
  const publicItems = [...radar.items, ...community.items]
    .filter(item => {
      if (!isCurrentlyActive(item)) return false;
      if (item.kind !== 'job_offer') return true;
      if (!item.verified || item.review) return false;
      if (!item.workCommunes?.some(commune => PILOT.some(target => normalizeText(target).toLocaleLowerCase('es-CL') === normalizeText(commune).toLocaleLowerCase('es-CL')))) return false;
      const sourceEvidence = [item.title, item.company, item.note, item.url, item.sourceDomain].filter(Boolean).join(' ');
      if (unsafeContentReason(sourceEvidence, item.url)) return false;
      const publishedTs = parseDiscoveryDate(item.sourcePublishedAt || item.date);
      if (!publishedTs) return false;
      if (staleDiscoveryDate(new Date(publishedTs).toISOString())) return false;
      return true;
    })
    .sort((a,b) => Date.parse(b.createdAt) - Date.parse(a.createdAt))
    .map(publicRecord);
  const jobOffers = publicItems.filter(item => item.kind === 'job_offer');
  const totalJobOffers = jobOffers.length;
  const totalVerifiedJobOffers = jobOffers.filter(item => item.verified && !item.review).length;
  const totalProvisionalJobOffers = 0;
  const cutoff24h = Date.now() - 86400000;
  const communeStats: Record<string, CommuneStats> = {};
  const ensureCommune = (commune:string) => communeStats[commune] ??= { jobs:0, newJobs24h:0, people:0, needs:0, services:0 };
  for (const item of publicItems) {
    for (const commune of item.workCommunes) {
      const stat = ensureCommune(commune);
      if (item.kind === 'job_offer') {
        stat.jobs += 1;
        if (Date.parse(item.createdAt) >= cutoff24h) stat.newJobs24h += 1;
      } else if (item.kind === 'worker_available') stat.people += 1;
      else if (item.kind === 'worker_need') stat.needs += 1;
      else if (item.kind === 'service_request') stat.services += 1;
    }
  }
  const kindStats: KindStats = {
    jobs:jobOffers.length,
    people:publicItems.filter(item => item.kind === 'worker_available').length,
    needs:publicItems.filter(item => item.kind === 'worker_need').length,
    services:publicItems.filter(item => item.kind === 'service_request').length,
  };
  const pageCount = Math.max(1, Math.ceil(publicItems.length / PUBLIC_FEED_PAGE_SIZE));

  for (let page = 0; page < pageCount; page += 1) {
    const start = page * PUBLIC_FEED_PAGE_SIZE;
    const items = publicItems.slice(start, start + PUBLIC_FEED_PAGE_SIZE);
    const hasMore = page < pageCount - 1;
    const record: PublicFeedPage = {
      items,
      updatedAt,
      hasMore,
      nextCursor:hasMore ? String(page + 1) : undefined,
      pageSize:PUBLIC_FEED_PAGE_SIZE,
      totalItems:publicItems.length,
      totalJobOffers,
      totalVerifiedJobOffers,
      totalProvisionalJobOffers,
      communeStats,
      kindStats,
    };
    await writeSingleRecord(publicFeedTable(page), record as unknown as Record<string, unknown>);
  }

  const previousPageCount = control.items[0]?.pageCount ?? 0;
  for (let page = pageCount; page < previousPageCount; page += 1) {
    const old = await db.list<Record<string, unknown>>(publicFeedTable(page), { limit:1 });
    if (old.items[0]) await db.delete(publicFeedTable(page), [old.items[0].id]);
  }
  await writeSingleRecord('public_feed_control', { pageCount, updatedAt, itemCount:publicItems.length, totalJobOffers, totalVerifiedJobOffers, totalProvisionalJobOffers, communeStats, kindStats });
  return { pageCount, itemCount:publicItems.length, totalJobOffers, totalVerifiedJobOffers, totalProvisionalJobOffers, communeStats, kindStats, updatedAt };
}

